-- Easy Beans (business 1): Santa Roaster, the specialty roaster in Soho, Málaga (Ideas del Café 2018 S.L.),
-- added on Suppliers as an active coffee roaster, and its Decaffeinated Colombia added to the Coffees page as
-- a coffee in use, with the roaster's photo of it and its page on their shop. From santaroaster.com
-- (November 2026): the shop and roastery at C/ Tomás Heredia 3, the registered office at C/ Trinidad Grund 22,
-- the decaf's farm, variety and notes, and the shop's price for a 1 kg bag (€42; 250 g is €14).
-- When the café has added either already, its empty details are filled in and it's made active again
-- if it was archived; nothing else changes. Easy Beans is business 1 when it's named so or Aron is on
-- its team (as in the `coffee_suppliers` migration); anywhere else nothing changes, and running it
-- again changes nothing.
do $$
declare
  v_name    constant text := 'Santa Roaster';
  v_legal   constant text := 'Ideas del Café 2018 S.L.';
  v_tax_id  constant text := 'B93627834';
  v_phone   constant text := '+34 625 811 471';
  v_email   constant text := 'info@santaroaster.com';
  v_website constant text := 'https://santaroaster.com/en/';
  v_address constant text := 'C/ Tomás Heredia 3, Soho, 29001 Málaga';
  v_notes   constant text := 'Specialty roaster in Soho, Málaga. Free collection at the shop and roastery '
                          || '(C/ Tomás Heredia 3), Monday to Friday 9:00–18:00. Ships to mainland Spain and '
                          || 'Portugal in 24–72 working hours. Registered office: C/ Trinidad Grund 22, 29001 Málaga. '
                          || 'Coffee school: escuela@santaroaster.com.';
  v_coffee  constant text := 'Colombia Decaf';
  v_link    constant text := 'https://santaroaster.com/en/product/decaffeinated-colombian-coffee/';
  v_tasting constant text := 'Almond, panela and clove. Sugar-cane (EA) decaf of red and yellow Caturra from '
                          || 'Elias and Shady Bayter, at 1,450 m. SCA 84.';
  v_photo   constant text := 'data:image/jpeg;base64,';
  v_sup uuid;
  v_id uuid;
begin
  if not exists (select 1 from public.business b
                  where b.id = 1
                    and (b.name ~* 'easy\s*beans'
                         or exists (select 1 from public.profiles p where p.business_id = 1 and p.full_name ~* '^\s*aron\M'))) then
    return;
  end if;
  -- Named, so the rules and the audit see Easy Beans (a migration runs signed out).
  perform set_config('app.business_id', '1', true);

  -- Suppliers: the roaster, active (bought from now).
  select s.id into v_sup
    from public.suppliers s
   where s.business_id = 1
     and (s.name ~* '\msanta''?s?\s*roaster\M' or s.legal_name ~* '\mideas\s+del\s+caf'
          or s.website ~* '^https?://(www\.)?santaroaster\.com' or s.email ~* '@santaroaster\.com$')
   order by s.active desc, s.created_at
   limit 1;
  if v_sup is null then
    insert into public.suppliers (business_id, name, legal_name, tax_id, kind, supplies, phone, email, website, address, active, notes)
    values (1, v_name, v_legal, v_tax_id, 'Coffee roaster', array['coffee'], v_phone, v_email, v_website, v_address, true, v_notes);
  else
    update public.suppliers
       set legal_name = coalesce(legal_name, v_legal),
           tax_id = coalesce(tax_id, v_tax_id),
           kind = coalesce(kind, 'Coffee roaster'),
           supplies = case when 'coffee' = any(supplies) then supplies else supplies || array['coffee'] end,
           phone = coalesce(phone, v_phone),
           email = coalesce(email, v_email),
           website = coalesce(website, v_website),
           address = coalesce(address, v_address),
           active = true,
           notes = coalesce(notes, v_notes)
     where id = v_sup;
  end if;

  -- Coffees: the decaf, in use.
  select c.id into v_id
    from public.coffees c
   where c.business_id = 1 and c.name ~* 'colombia' and c.name ~* 'decaf|descafeinado'
   order by c.active desc, c.created_at
   limit 1;
  if v_id is null then
    insert into public.coffees (business_id, name, country, region, roaster, tasting_notes, brew, bag_grams, bag_price,
                                active, photo, link, sort)
    values (1, v_coffee, 'CO', 'El Vergel, Fresno (Tolima)', v_name, v_tasting, 'espresso', 1000, 42.00,
            true, v_photo, v_link, coalesce((select max(sort) + 1 from public.coffees where business_id = 1), 1));
  else
    update public.coffees
       set country = coalesce(country, 'CO'),
           region = coalesce(region, 'El Vergel, Fresno (Tolima)'),
           roaster = coalesce(roaster, v_name),
           tasting_notes = coalesce(tasting_notes, v_tasting),
           -- The bag only when it has neither, so a size and a price always go together.
           bag_grams = case when bag_grams is null and bag_price is null then 1000 else bag_grams end,
           bag_price = case when bag_grams is null and bag_price is null then 42.00 else bag_price end,
           active = true,
           photo = coalesce(photo, v_photo),
           link = coalesce(link, v_link)
     where id = v_id;
  end if;

  perform set_config('app.business_id', '', true);
end $$;
